using System.ComponentModel.DataAnnotations;
using DineFlow.Application.Bills;
using DineFlow.Application.Transactions;
using DineFlow.Domain.Payments;

namespace DineFlow.Application.PaymentLinks;

public enum ValidityUnit { Hours, Days }

/// <param name="ClientRequestId">Generated by the merchant app per link; a retry returns the same link.</param>
/// <param name="AmountMinor">What the customer pays, inclusive of taxes and charges, before any tip.</param>
/// <param name="ValidFor">How long the link stays active, in <paramref name="ValidityUnit"/> (1 hour up to 90 days).</param>
/// <param name="CustomerEmail">When set, the customer is e-mailed the link straight away (P1-LNK-03).</param>
public record CreatePaymentLinkRequest(
    [Required] Guid VenueId,
    [Required] Guid ClientRequestId,
    [Range(1, PaymentLink.MaxAmountMinor)] long AmountMinor,
    [StringLength(PaymentLink.MaxReferenceLength)] string? Reference,
    bool AllowSplit,
    bool RequestTip,
    [Range(1, 2160)] int ValidFor,
    ValidityUnit ValidityUnit,
    [EmailAddress, StringLength(254)] string? CustomerEmail);

public record PaymentLinkNotifyRequest([Required, EmailAddress, StringLength(254)] string Email);

public enum PaymentLinkFilter { All, Active, Paid, Expired, Cancelled }

/// <param name="Search">A link code (e.g. PL-1A2B), the merchant's reference, a customer e-mail or an amount.</param>
public record PaymentLinkQuery(
    [Required] Guid VenueId,
    PaymentLinkFilter Status = PaymentLinkFilter.All,
    [StringLength(60)] string? Search = null,
    [Range(1, 10_000)] int Page = 1,
    [Range(1, 100)] int PageSize = 25);

/// <param name="PaidMinor">Paid towards the amount so far (tips not included).</param>
/// <param name="Url">The public link to share; the same every time it's shown.</param>
public record PaymentLinkRowDto(
    Guid Id,
    string Code,
    string? Reference,
    PaymentLinkStatus Status,
    string Currency,
    long AmountMinor,
    long PaidMinor,
    long TipsMinor,
    int PaymentCount,
    bool AllowSplit,
    bool RequestTip,
    string? CustomerEmail,
    DateTimeOffset CreatedAt,
    DateTimeOffset ExpiresAt,
    DateTimeOffset? PaidAt,
    string Url);

/// <summary>How many of the venue's links are in each state, for the filter chips (search applied, status not).</summary>
public record PaymentLinkCountsDto(int All, int Active, int Paid, int Expired, int Cancelled);

public record PaymentLinkPageDto(IReadOnlyList<PaymentLinkRowDto> Items, int Total, int Page, int PageSize, PaymentLinkCountsDto Counts);

/// <summary>One payment made through the link; it opens in Transactions.</summary>
public record PaymentLinkPaymentDto(
    Guid Id,
    string Reference,
    TransactionState State,
    PaymentMethod Method,
    string? CardBrand,
    string? CardLast4,
    PaymentMode Mode,
    int? Shares,
    int? SplitPeople,
    long BillAmountMinor,
    long TipMinor,
    long AmountMinor,
    long RefundedMinor,
    DateTimeOffset CreatedAt,
    DateTimeOffset? SucceededAt);

public record PaymentLinkDetailDto(
    PaymentLinkRowDto Summary,
    long RemainingMinor,
    string? CreatedBy,
    DateTimeOffset? CustomerNotifiedAt,
    DateTimeOffset? CancelledAt,
    string? CancelledBy,
    IReadOnlyList<PaymentLinkPaymentDto> Payments,
    IReadOnlyList<TimelineEventDto> Timeline);

// ---- Public (the customer's payment page) ----

/// <param name="BranchNameAr">The branch's name for customers reading Arabic; null when it has none.</param>
public record LinkVenueDto(string BrandName, string BranchName, string? LogoUrl, string BrandColor, string DefaultLocale, string? BranchNameAr = null);

/// <summary>
/// The link as the customer sees it (blueprint 9.1 GET /v1/public/payment-links/{token}, 4.2
/// "Payment Link Checkout"): who's asking, how much, what's been paid, and how they can pay.
/// </summary>
/// <param name="AvailableMinor">What this customer can pay now: what's left minus payments other people have in progress.</param>
/// <param name="Tips">Disabled unless the merchant asked for a tip and the venue takes tips.</param>
public record PublicPaymentLinkDto(
    string Code,
    string? Reference,
    PaymentLinkStatus Status,
    LinkVenueDto Venue,
    string Currency,
    long AmountMinor,
    long PaidMinor,
    long RemainingMinor,
    long AvailableMinor,
    bool PaymentInProgress,
    bool AllowSplit,
    TipSettingsDto Tips,
    IReadOnlyList<PaymentMethod> Methods,
    string TermsVersion,
    string TermsUrl,
    DateTimeOffset ExpiresAt);

/// <param name="Mode">Full (what's left), Equal (<paramref name="Shares"/> of <paramref name="People"/> shares of the link's amount) or Custom; split modes need the link to allow splitting.</param>
/// <param name="ExpectedAmountMinor">What the customer saw before tip; if it changed, nothing is charged.</param>
public record CreateLinkPaymentRequest(
    [Required] Guid ClientRequestId,
    [Required] PaymentMethod Method,
    PaymentMode Mode,
    [Range(2, 50)] int? People,
    [Range(1, 50)] int? Shares,
    [Range(1, PaymentLink.MaxAmountMinor)] long? AmountMinor,
    [Range(0, PaymentLink.MaxAmountMinor)] long TipMinor,
    [Range(1, PaymentLink.MaxAmountMinor)] long ExpectedAmountMinor,
    bool AcceptTerms);

/// <param name="RemainingMinor">Left to pay on the link (known once this payment succeeded, otherwise current).</param>
public record LinkPaymentDto(
    Guid Id,
    string Reference,
    PaymentStatus Status,
    PaymentMethod Method,
    PaymentMode Mode,
    int? Shares,
    int? SplitPeople,
    string Currency,
    long BillAmountMinor,
    long TipMinor,
    long AmountMinor,
    string? CardBrand,
    string? CardLast4,
    string? FailureReason,
    /// <summary>The provider's page to send the customer to while the payment needs their action.</summary>
    string? CheckoutUrl,
    DateTimeOffset CreatedAt,
    DateTimeOffset? SucceededAt,
    long RemainingMinor,
    bool FullyPaid);
